(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-970":{scenario:{company:"Chargio Mobility Hub",supervisor:{name:"Viên Thảo Nguyên",role:{vi:"Trưởng phòng Vận hành Mạng lưới Sạc",en:"Charging Network Operations Manager"}},ref_code:"EVC-4127",title:{vi:"Đúng chế độ sạc. Đủ công suất lưới.",en:"Right charging mode. Enough grid capacity."},brief:{vi:"Bạn hoàn thiện hồ sơ đăng ký đấu nối EVC-4127 cho trạm sạc ST-27 tại bãi xe một trung tâm thương mại: 6 trụ sạc nhanh DC 120 kW đầu nối CCS2 (bộ chỉnh lưu đặt trong trụ) và 10 trụ AC 11 kW; phụ tải phụ trợ 23 kW. Hệ số đồng thời DC 0.8, AC 0.6; hệ số công suất 0.95. Sửa chế độ sạc theo IEC 61851-1 của trụ DC và công suất đăng ký đấu nối (kVA) trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"You are completing grid connection application EVC-4127 for charging site ST-27 in a shopping mall car park: 6 DC fast chargers of 120 kW with CCS2 connectors (rectifier inside the charger) and 10 AC chargers of 11 kW; auxiliary load 23 kW. Diversity factor DC 0.8, AC 0.6; power factor 0.95. Correct the IEC 61851-1 charging mode of the DC units and the grid connection capacity (kVA) in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Thiết kế điện & thông số trụ sạc đã duyệt · EVC-4127",en:"Approved electrical design & charger specs · EVC-4127"},fields:[{id:"DC_MODE",label:{vi:"Chế độ sạc trụ DC (IEC 61851-1)",en:"DC charger mode (IEC 61851-1)"},initial:"MODE-3",expected:"MODE-4",choices:["MODE-2","MODE-3","MODE-4"],reference:"Bảng thông số kỹ thuật trụ sạc",hint:{vi:"Chế độ 3 cấp AC cho bộ sạc trên xe; khi bộ chỉnh lưu nằm trong trụ và cấp DC trực tiếp cho pin thì là chế độ khác.",en:"Mode 3 supplies AC to the on-board charger; when the rectifier sits in the unit and feeds DC to the battery, it is another mode."}},{id:"GRID_KVA",label:{vi:"Công suất đăng ký đấu nối (kVA)",en:"Grid connection capacity (kVA)"},initial:"665",expected:"700",reference:"Bảng tính phụ tải trạm sạc",ref_value:{vi:"6 x 120 kW DC (đồng thời 0.8); 10 x 11 kW AC (0.6); phụ trợ 23 kW; cos phi 0.95",en:"6 x 120 kW DC (diversity 0.8); 10 x 11 kW AC (0.6); auxiliary 23 kW; power factor 0.95"},hint:{vi:"Bản nháp mới dừng ở công suất tác dụng kW; công suất đăng ký với điện lực tính bằng kVA.",en:"The draft stops at real power in kW; the capacity requested from the utility is in kVA."}}],sop32:{vi:"Công suất đăng ký (kVA) = (số trụ DC x công suất x hệ số đồng thời DC + số trụ AC x công suất x hệ số đồng thời AC + phụ tải phụ trợ) / hệ số công suất.",en:"Requested capacity (kVA) = (DC units x rating x DC diversity + AC units x rating x AC diversity + auxiliary load) / power factor."},context:{label:"CPMS / EVC-4127",metrics:[{label:{vi:"Trụ sạc DC",en:"DC chargers"},value:"6 x 120 kW"},{label:{vi:"Trụ sạc AC",en:"AC chargers"},value:"10 x 11 kW"},{label:{vi:"Phụ tải phụ trợ",en:"Auxiliary load"},value:"23 kW"},{label:{vi:"Hệ số công suất",en:"Power factor"},value:"0.95"}]},crisis:{vi:"Nhà thầu nhắn: “Đấu tạm trạm sạc vào tủ điện tòa nhà để khai trương thứ Bảy, chưa cần chờ điện lực nghiệm thu hay thử RCD. Chủ đầu tư đã mời báo chí rồi, lùi lịch là mất mặt.”",en:"The contractor messages you: “Hook the chargers temporarily onto the building switchboard to open on Saturday, no need to wait for utility acceptance or RCD tests. The owner has invited the press, postponing would be embarrassing.”"},options:{safe:{vi:"Không cấp điện khi chưa thử nghiệm, nghiệm thu và được điện lực chấp thuận; báo trưởng phòng và chủ đầu tư bằng văn bản, đề xuất lịch khai trương theo tiến độ nghiệm thu.",en:"Do not energize before testing, acceptance and utility approval; inform the manager and owner in writing and propose an opening date aligned with acceptance."},shortcut:{vi:"Đấu tạm vào tủ tòa nhà để kịp khai trương, làm thủ tục nghiệm thu bổ sung sau.",en:"Connect temporarily to the building switchboard to open on time and complete acceptance later."},wait:{vi:"Không phản hồi, để nhà thầu và chủ đầu tư tự xử lý.",en:"Do not reply and let the contractor and owner sort it out."}},questions:{vi:["Vì sao trụ DC 120 kW thuộc MODE-4? Dữ liệu nào cho ra công suất đăng ký 700 kVA?","Đấu tạm vào tủ tòa nhà khi chưa nghiệm thu gây rủi ro gì về an toàn điện, cháy nổ và pháp lý? Bạn đề xuất phương án nào?"],en:["Why are the 120 kW DC units MODE-4? Which data gives the corrected connection capacity?","What electrical, fire and legal risks come from a temporary hookup before acceptance? What alternative do you propose?"]},hints:{vi:["Xác định bộ chuyển đổi AC/DC nằm ở đâu: trên xe hay trong trụ sạc.","Cộng phụ tải có tính hệ số đồng thời rồi chia hệ số công suất theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không cấp điện trước nghiệm thu; báo cáo áp lực và đề xuất lịch hợp lệ."],en:["Find where the AC/DC converter sits: on the vehicle or inside the charger.","Add the diversified loads, then divide by power factor per SOP 3.2.","Re-read SOP 4.2: never energize before acceptance; report the pressure and propose a compliant schedule."]}},learning:{summary:{vi:"Chuyên viên hạ tầng trạm sạc xe điện quy hoạch vị trí, tính toán phụ tải và đấu nối, giám sát lắp đặt, nghiệm thu và vận hành mạng lưới trụ sạc AC, DC. Nghề bảo đảm trạm sạc an toàn, sẵn sàng và hiệu quả kinh tế, đòi hỏi hiểu điện hạ áp, tiêu chuẩn sạc, giao thức OCPP, an toàn cháy và kỹ năng điều phối nhiều bên.",en:"An EV charging infrastructure specialist plans sites, sizes loads and grid connections, supervises installation, commissioning and operation of AC and DC charger networks. The role keeps sites safe, available and economically sound, and requires low-voltage electrical knowledge, charging standards, the OCPP protocol, fire safety and multi-party coordination."},responsibilities:{vi:["Khảo sát, chọn vị trí và dự báo nhu cầu sạc theo lưu lượng xe và hành vi người dùng.","Tính phụ tải, hệ số đồng thời, công suất đấu nối và phương án quản lý tải động.","Lập hồ sơ đấu nối, phối hợp điện lực, nhà thầu và chủ mặt bằng trong thi công.","Nghiệm thu trụ sạc: thử RCD, nối đất, giao tiếp OCPP và phiên sạc thực tế.","Giám sát vận hành, xử lý sự cố, bảo trì phòng ngừa và báo cáo hiệu suất mạng lưới."],en:["Survey and select sites and forecast charging demand from traffic and user behavior.","Calculate loads, diversity, connection capacity and dynamic load management.","Prepare connection applications and coordinate the utility, contractors and landlords.","Commission chargers: RCD and earthing tests, OCPP communication and live sessions.","Monitor operations, handle faults, run preventive maintenance and report network performance."]},competencies:[{name:{vi:"Điện hạ áp & đấu nối",en:"Low-voltage & grid connection"},desc:{vi:"Tính phụ tải, chọn cáp, bảo vệ, nối đất và làm việc với yêu cầu của điện lực.",en:"Size loads, cables, protection and earthing and meet utility requirements."}},{name:{vi:"Tiêu chuẩn sạc",en:"Charging standards"},desc:{vi:"Hiểu chế độ sạc, chuẩn đầu nối, giao tiếp xe với trụ và trụ với hệ thống quản lý.",en:"Understand charging modes, connector standards, vehicle and back-end communication."}},{name:{vi:"Điều phối vận hành",en:"Operations coordination"},desc:{vi:"Lập kế hoạch thi công, nghiệm thu, bảo trì và điều phối đội kỹ thuật hiện trường.",en:"Plan installation, commissioning and maintenance and coordinate field teams."}},{name:{vi:"Phân tích dữ liệu sạc",en:"Charging data analysis"},desc:{vi:"Theo dõi uptime, tỷ lệ phiên thành công, hệ số sử dụng và đề xuất tối ưu.",en:"Track uptime, session success and utilization and propose improvements."}},{name:{vi:"An toàn & tuân thủ",en:"Safety & compliance"},desc:{vi:"Không cấp điện khi chưa nghiệm thu, tuân thủ an toàn điện và an toàn cháy bãi xe.",en:"Never energize before acceptance and comply with electrical and car park fire safety."}}],knowledge:{vi:["IEC 61851-1 về yêu cầu chung của hệ thống sạc dẫn điện cho xe điện và các chế độ sạc 1-4.","IEC 62196 về phích, ổ cắm và đầu nối sạc: Type 2 cho AC, CCS2 (cấu hình FF) cho DC.","IEC 60364-7-722 về lắp đặt hạ áp cấp điện cho xe điện: RCD, bảo vệ quá dòng, nối đất.","OCPP 1.6J và 2.0.1 cho giao tiếp trụ với hệ thống quản lý; ISO 15118 cho giao tiếp xe với trụ.","QCVN 06:2022/BXD về an toàn cháy cho nhà và công trình, áp dụng khi bố trí trạm sạc trong bãi xe."],en:["IEC 61851-1 general requirements for EV conductive charging systems and charging modes 1-4.","IEC 62196 plugs, sockets and couplers: Type 2 for AC, CCS2 (configuration FF) for DC.","IEC 60364-7-722 low-voltage installations supplying electric vehicles: RCD, overcurrent protection, earthing.","OCPP 1.6J and 2.0.1 for charger to back-end communication; ISO 15118 for vehicle to charger communication.","QCVN 06:2022/BXD on fire safety of buildings, applied when placing chargers in car parks."]},tools:["Hệ thống quản lý điểm sạc (CPMS) qua OCPP","Máy thử trụ sạc và thử RCD","Máy phân tích chất lượng điện","Phần mềm thiết kế điện hạ áp","Bản đồ GIS mạng lưới trạm","Công cụ dự báo nhu cầu sạc"],kpis:{vi:["Thời gian sẵn sàng hoạt động của trụ sạc (uptime %).","Tỷ lệ phiên sạc thành công ngay lần đầu.","Hệ số sử dụng trụ sạc (giờ sạc mỗi ngày).","Thời gian trung bình khắc phục sự cố (MTTR)."],en:["Charger uptime (%).","First-attempt charging session success rate.","Charger utilization (charging hours per day).","Mean time to repair (MTTR)."]},day:[{time:"07:30",vi:"Xem bảng điều khiển CPMS: trụ ngoại tuyến, lỗi phiên sạc và cảnh báo nhiệt.",en:"Check the CPMS dashboard: offline chargers, failed sessions and thermal alarms."},{time:"09:00",vi:"Điều phối đội hiện trường xử lý trụ lỗi theo mức ưu tiên.",en:"Dispatch field crews to faulty chargers by priority."},{time:"11:00",vi:"Làm việc với điện lực về hồ sơ đấu nối và lịch nghiệm thu trạm mới.",en:"Work with the utility on connection files and acceptance dates for new sites."},{time:"14:00",vi:"Giám sát nghiệm thu: thử RCD, điện trở nối đất và phiên sạc thực tế.",en:"Supervise commissioning: RCD tests, earthing resistance and live sessions."},{time:"16:30",vi:"Phân tích hệ số sử dụng, đề xuất cấu hình quản lý tải và báo cáo tuần.",en:"Analyze utilization, propose load management settings and write the weekly report."}],mistakes:{vi:["Đăng ký công suất theo kW mà quên chia hệ số công suất, dẫn tới thiếu dung lượng máy biến áp.","Cộng công suất định mức của mọi trụ mà không áp dụng hệ số đồng thời hoặc quản lý tải động.","Cấp điện tạm trước khi thử RCD, nối đất và được điện lực chấp thuận."],en:["Requesting capacity in kW without dividing by power factor, leaving the transformer undersized.","Adding every charger's rating without diversity or dynamic load management.","Energizing temporarily before RCD and earthing tests and utility approval."]},career:[{vi:"Kỹ thuật viên lắp đặt và bảo trì trụ sạc",en:"Charger installation and maintenance technician"},{vi:"Chuyên viên hạ tầng trạm sạc",en:"EV charging infrastructure specialist"},{vi:"Trưởng nhóm triển khai và vận hành mạng lưới sạc",en:"Charging network deployment and operations lead"},{vi:"Giám đốc hạ tầng di chuyển điện",en:"E-mobility infrastructure director"}],glossary:[{term:"Mode 4",vi:"Chế độ sạc DC với bộ sạc đặt ngoài xe, cáp cố định trên trụ, dùng cho sạc nhanh.",en:"DC charging with an off-board charger and a tethered cable, used for fast charging."},{term:"CCS2",vi:"Hệ thống sạc kết hợp dùng chung cổng Type 2 với hai chân DC, phổ biến tại châu Âu và nhiều thị trường châu Á.",en:"Combined charging system sharing the Type 2 inlet with two DC pins, common in Europe and many Asian markets."},{term:"OCPP",vi:"Giao thức mở cho trụ sạc trao đổi dữ liệu với hệ thống quản lý điểm sạc.",en:"Open protocol for chargers to exchange data with the charge point management system."},{term:"DLM",vi:"Quản lý tải động: phân bổ công suất giữa các trụ để không vượt công suất đấu nối.",en:"Dynamic load management: sharing power across chargers within the connection limit."},{term:"Diversity factor",vi:"Hệ số đồng thời: tỷ lệ công suất thực tế cùng lúc so với tổng công suất định mức.",en:"The ratio of simultaneous actual demand to the total rated load."}],quiz:[{q:{vi:"4 trụ DC 60 kW, hệ số đồng thời 0.75, phụ trợ 10 kW, hệ số công suất 0.95. Công suất đăng ký là bao nhiêu?",en:"4 DC chargers of 60 kW, diversity 0.75, auxiliary 10 kW, power factor 0.95. What capacity should be requested?"},options:{vi:["240 kVA","190 kVA","200 kVA","263 kVA"],en:["240 kVA","190 kVA","200 kVA","263 kVA"]},answer:2,explain:{vi:"Công suất đăng ký = (4 x 60 x 0.75 + 10) / 0.95 = 190 / 0.95 = 200 kVA.",en:"Requested capacity = (4 x 60 x 0.75 + 10) / 0.95 = 190 / 0.95 = 200 kVA."}},{q:{vi:"Trụ sạc có bộ chỉnh lưu bên trong, cấp DC trực tiếp cho pin xe thuộc chế độ nào theo IEC 61851-1?",en:"A charger with an internal rectifier feeding DC directly to the battery is which IEC 61851-1 mode?"},options:{vi:["Mode 1","Mode 2","Mode 3","Mode 4"],en:["Mode 1","Mode 2","Mode 3","Mode 4"]},answer:3,explain:{vi:"Mode 4 là sạc DC với bộ sạc ngoài xe; Mode 3 cấp AC qua trụ chuyên dụng cho bộ sạc trên xe.",en:"Mode 4 is DC charging with an off-board charger; Mode 3 supplies AC through a dedicated unit to the on-board charger."}},{q:{vi:"Nhà thầu đề nghị đấu tạm trụ sạc vào tủ tòa nhà để kịp khai trương. Bạn làm gì?",en:"The contractor proposes a temporary hookup to the building switchboard to open on time. What do you do?"},options:{vi:["Từ chối, báo cáo bằng văn bản và đề xuất lịch theo tiến độ nghiệm thu","Đồng ý nếu chỉ chạy hai trụ","Đồng ý và thử RCD sau","Để nhà thầu tự quyết"],en:["Refuse, report in writing and propose a schedule tied to acceptance","Agree if only two chargers run","Agree and test RCDs later","Let the contractor decide"]},answer:0,explain:{vi:"Cấp điện khi chưa nghiệm thu có thể gây điện giật, cháy và vi phạm hợp đồng đấu nối.",en:"Energizing before acceptance risks electric shock, fire and a breach of the connection agreement."}},{q:{vi:"OCPP dùng để làm gì?",en:"What is OCPP used for?"},options:{vi:["Đo điện trở nối đất","Kết nối trụ sạc với hệ thống quản lý điểm sạc","Tính hệ số công suất","Kiểm tra pin xe"],en:["Measuring earthing resistance","Connecting chargers to the charge point management system","Calculating power factor","Testing the vehicle battery"]},answer:1,explain:{vi:"OCPP là giao thức mở giữa trụ sạc và hệ thống quản lý: phiên sạc, giá, giám sát và cập nhật từ xa.",en:"OCPP is the open protocol between chargers and the back-end: sessions, tariffs, monitoring and remote updates."}}],tools_en:["Charge point management system (CPMS) via OCPP","EV charger and RCD tester","Power quality analyzer","Low-voltage electrical design software","Charging network GIS map","Charging demand forecasting tool"]}}})})(window.KKR);
